CREATE TABLE "PREFIX_accessory" (
  "id_product_1" BIGINT NOT NULL,
  "id_product_2" BIGINT NOT NULL,
  PRIMARY KEY ("id_product_1", "id_product_2")
);

/* Address info associated with a user */
CREATE TABLE "PREFIX_address" (
  "id_address" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_country" BIGINT NOT NULL,
  "id_state" BIGINT DEFAULT NULL,
  "id_customer" BIGINT NOT NULL DEFAULT '0',
  "id_manufacturer" BIGINT NOT NULL DEFAULT '0',
  "id_supplier" BIGINT NOT NULL DEFAULT '0',
  "id_warehouse" BIGINT NOT NULL DEFAULT '0',
  "alias" VARCHAR(32) NOT NULL,
  "company" VARCHAR(255) DEFAULT NULL,
  "lastname" VARCHAR(255) NOT NULL,
  "firstname" VARCHAR(255) NOT NULL,
  "address1" VARCHAR(128) NOT NULL,
  "address2" VARCHAR(128) DEFAULT NULL,
  "postcode" VARCHAR(12) DEFAULT NULL,
  "city" VARCHAR(64) NOT NULL,
  "other" TEXT,
  "phone" VARCHAR(32) DEFAULT NULL,
  "phone_mobile" VARCHAR(32) DEFAULT NULL,
  "vat_number" VARCHAR(32) DEFAULT NULL,
  "dni" VARCHAR(16) DEFAULT NULL,
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  "active" SMALLINT NOT NULL DEFAULT '1',
  "deleted" SMALLINT NOT NULL DEFAULT '0',
  PRIMARY KEY ("id_address")
);
CREATE INDEX "PREFIX_address_address_customer" ON "PREFIX_address" ("id_customer");
CREATE INDEX "PREFIX_address_id_country" ON "PREFIX_address" ("id_country");
CREATE INDEX "PREFIX_address_id_state" ON "PREFIX_address" ("id_state");
CREATE INDEX "PREFIX_address_id_manufacturer" ON "PREFIX_address" ("id_manufacturer");
CREATE INDEX "PREFIX_address_id_supplier" ON "PREFIX_address" ("id_supplier");
CREATE INDEX "PREFIX_address_id_warehouse" ON "PREFIX_address" ("id_warehouse");

/* Used for search, if a search string is present inside the table, search the alias as well */
CREATE TABLE "PREFIX_alias" (
  "id_alias" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "alias" VARCHAR(191) NOT NULL,
  "search" VARCHAR(255) NOT NULL,
  "active" SMALLINT NOT NULL DEFAULT '1',
  PRIMARY KEY ("id_alias"),
  CONSTRAINT "PREFIX_alias_alias" UNIQUE ("alias")
);

/* Contains all virtual products (attachements, like images, files, ...) */
CREATE TABLE "PREFIX_attachment" (
  "id_attachment" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "file" VARCHAR(40) NOT NULL,
  "file_name" VARCHAR(255) NOT NULL,
  "file_size" BIGINT NOT NULL DEFAULT '0',
  "mime" VARCHAR(128) NOT NULL,
  PRIMARY KEY ("id_attachment")
);

/* Name / Description linked to an attachment, localised */
CREATE TABLE "PREFIX_attachment_lang" (
  "id_attachment" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_lang" BIGINT NOT NULL,
  "name" VARCHAR(255) DEFAULT NULL,
  "description" TEXT,
  PRIMARY KEY ("id_attachment", "id_lang")
);

/* Relationship between a product and an attachment */
CREATE TABLE "PREFIX_product_attachment" (
  "id_product" BIGINT NOT NULL,
  "id_attachment" BIGINT NOT NULL,
  PRIMARY KEY ("id_product", "id_attachment")
);

/* Describe the carrier informations */
CREATE TABLE "PREFIX_carrier" (
  "id_carrier" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_reference" BIGINT NOT NULL,
  "name" VARCHAR(64) NOT NULL,
  "url" VARCHAR(255) DEFAULT NULL,
  "active" SMALLINT NOT NULL DEFAULT '0',
  "deleted" SMALLINT NOT NULL DEFAULT '0',
  "shipping_handling" SMALLINT NOT NULL DEFAULT '1',
  "range_behavior" SMALLINT NOT NULL DEFAULT '0',
  "is_module" SMALLINT NOT NULL DEFAULT '0',
  "is_free" SMALLINT NOT NULL DEFAULT '0',
  "shipping_external" SMALLINT NOT NULL DEFAULT '0',
  "need_range" SMALLINT NOT NULL DEFAULT '0',
  "external_module_name" VARCHAR(64) DEFAULT NULL,
  "shipping_method" INTEGER NOT NULL DEFAULT '0',
  "position" BIGINT NOT NULL DEFAULT '0',
  "max_width" INTEGER DEFAULT '0',
  "max_height" INTEGER DEFAULT '0',
  "max_depth" INTEGER DEFAULT '0',
  "max_weight" NUMERIC(20, 6) DEFAULT '0',
  "grade" INTEGER DEFAULT '0',
  PRIMARY KEY ("id_carrier")
);
CREATE INDEX "PREFIX_carrier_deleted" ON "PREFIX_carrier" ("deleted", "active");
CREATE INDEX "PREFIX_carrier_reference" ON "PREFIX_carrier" ("id_reference", "deleted", "active");

/* Localization carrier infos */
CREATE TABLE "PREFIX_carrier_lang" (
  "id_carrier" BIGINT NOT NULL,
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_lang" BIGINT NOT NULL,
  "delay" VARCHAR(512) DEFAULT NULL,
  PRIMARY KEY ("id_lang", "id_shop", "id_carrier")
);

/* Association between a zone and a carrier */
CREATE TABLE "PREFIX_carrier_zone" (
  "id_carrier" BIGINT NOT NULL,
  "id_zone" BIGINT NOT NULL,
  PRIMARY KEY ("id_carrier", "id_zone")
);

/* Describe the metadata associated with the carts */
CREATE TABLE "PREFIX_cart" (
  "id_cart" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_shop_group" BIGINT NOT NULL DEFAULT '1',
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_carrier" BIGINT NOT NULL,
  "delivery_option" TEXT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "id_address_delivery" BIGINT NOT NULL,
  "id_address_invoice" BIGINT NOT NULL,
  "id_currency" BIGINT NOT NULL,
  "id_customer" BIGINT NOT NULL,
  "id_guest" BIGINT NOT NULL,
  "secure_key" VARCHAR(32) NOT NULL DEFAULT '-1',
  "recyclable" SMALLINT NOT NULL DEFAULT '1',
  "gift" SMALLINT NOT NULL DEFAULT '0',
  "gift_message" TEXT,
  "mobile_theme" SMALLINT NOT NULL DEFAULT '0',
  "allow_seperated_package" SMALLINT NOT NULL DEFAULT '0',
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  "checkout_session_data" TEXT NULL,
  PRIMARY KEY ("id_cart")
);
CREATE INDEX "PREFIX_cart_cart_customer" ON "PREFIX_cart" ("id_customer");
CREATE INDEX "PREFIX_cart_id_address_delivery" ON "PREFIX_cart" ("id_address_delivery");
CREATE INDEX "PREFIX_cart_id_address_invoice" ON "PREFIX_cart" ("id_address_invoice");
CREATE INDEX "PREFIX_cart_id_carrier" ON "PREFIX_cart" ("id_carrier");
CREATE INDEX "PREFIX_cart_id_lang" ON "PREFIX_cart" ("id_lang");
CREATE INDEX "PREFIX_cart_id_currency" ON "PREFIX_cart" ("id_currency");
CREATE INDEX "PREFIX_cart_id_guest" ON "PREFIX_cart" ("id_guest");
CREATE INDEX "PREFIX_cart_id_shop_group" ON "PREFIX_cart" ("id_shop_group");
CREATE INDEX "PREFIX_cart_id_shop_2" ON "PREFIX_cart" ("id_shop", "date_upd");
CREATE INDEX "PREFIX_cart_id_shop" ON "PREFIX_cart" ("id_shop", "date_add");

/* Contains all the promo code rules */
CREATE TABLE "PREFIX_cart_rule" (
  "id_cart_rule" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_customer" BIGINT NOT NULL DEFAULT '0',
  "date_from" TIMESTAMP NOT NULL,
  "date_to" TIMESTAMP DEFAULT NULL,
  "description" TEXT,
  "quantity" BIGINT DEFAULT '0',
  "quantity_per_user" BIGINT DEFAULT '0',
  "priority" BIGINT NOT NULL DEFAULT 1,
  "partial_use" SMALLINT NOT NULL DEFAULT '0',
  "code" VARCHAR(254) NOT NULL,
  "minimum_amount" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "minimum_amount_tax" SMALLINT NOT NULL DEFAULT '0',
  "minimum_amount_currency" BIGINT NOT NULL DEFAULT '0',
  "minimum_amount_shipping" SMALLINT NOT NULL DEFAULT '0',
  "country_restriction" SMALLINT NOT NULL DEFAULT '0',
  "carrier_restriction" SMALLINT NOT NULL DEFAULT '0',
  "group_restriction" SMALLINT NOT NULL DEFAULT '0',
  "cart_rule_restriction" SMALLINT NOT NULL DEFAULT '0',
  "product_restriction" SMALLINT NOT NULL DEFAULT '0',
  "shop_restriction" SMALLINT NOT NULL DEFAULT '0',
  "free_shipping" SMALLINT NOT NULL DEFAULT '0',
  "reduction_percent" NUMERIC(5, 2) NOT NULL DEFAULT '0.00',
  "reduction_amount" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "reduction_tax" SMALLINT NOT NULL DEFAULT '0',
  "reduction_currency" BIGINT NOT NULL DEFAULT '0',
  "reduction_product" INTEGER NOT NULL DEFAULT '0',
  "reduction_exclude_special" SMALLINT NOT NULL DEFAULT '0',
  "gift_product" BIGINT NOT NULL DEFAULT '0',
  "gift_product_attribute" BIGINT NOT NULL DEFAULT '0',
  "highlight" SMALLINT NOT NULL DEFAULT '0',
  "active" SMALLINT NOT NULL DEFAULT '0',
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  "id_cart_rule_type" BIGINT DEFAULT NULL,
  "minimum_product_quantity" BIGINT NOT NULL DEFAULT 0,
  "total_quantity" BIGINT DEFAULT NULL,
  PRIMARY KEY ("id_cart_rule")
);
CREATE INDEX "PREFIX_cart_rule_id_customer" ON "PREFIX_cart_rule" ("id_customer", "active", "date_to");
CREATE INDEX "PREFIX_cart_rule_group_restriction" ON "PREFIX_cart_rule" ("group_restriction", "active", "date_to");
CREATE INDEX "PREFIX_cart_rule_id_customer_2" ON "PREFIX_cart_rule" ("id_customer", "active", "highlight", "date_to");
CREATE INDEX "PREFIX_cart_rule_group_restriction_2" ON "PREFIX_cart_rule" ("group_restriction", "active", "highlight", "date_to");
CREATE INDEX "PREFIX_cart_rule_date_from" ON "PREFIX_cart_rule" ("date_from");
CREATE INDEX "PREFIX_cart_rule_date_to" ON "PREFIX_cart_rule" ("date_to");
CREATE INDEX "PREFIX_cart_rule_id_cart_rule_type" ON "PREFIX_cart_rule" ("id_cart_rule_type");

/* Localized name assocatied with a promo code */
CREATE TABLE "PREFIX_cart_rule_lang" (
  "id_cart_rule" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "name" VARCHAR(254) NOT NULL,
  PRIMARY KEY ("id_cart_rule", "id_lang")
);

/* Country associated with a promo code */
CREATE TABLE "PREFIX_cart_rule_country" (
  "id_cart_rule" BIGINT NOT NULL,
  "id_country" BIGINT NOT NULL,
  PRIMARY KEY ("id_cart_rule", "id_country")
);

/* User group associated with a promo code */
CREATE TABLE "PREFIX_cart_rule_group" (
  "id_cart_rule" BIGINT NOT NULL,
  "id_group" BIGINT NOT NULL,
  PRIMARY KEY ("id_cart_rule", "id_group")
);

/* Carrier associated with a promo code */
CREATE TABLE "PREFIX_cart_rule_carrier" (
  "id_cart_rule" BIGINT NOT NULL,
  "id_carrier" BIGINT NOT NULL,
  PRIMARY KEY ("id_cart_rule", "id_carrier")
);

/* Allowed combination of promo code */
CREATE TABLE "PREFIX_cart_rule_combination" (
  "id_cart_rule_1" BIGINT NOT NULL,
  "id_cart_rule_2" BIGINT NOT NULL,
  PRIMARY KEY ("id_cart_rule_1", "id_cart_rule_2")
);
CREATE INDEX "PREFIX_cart_rule_combination_id_cart_rule_1" ON "PREFIX_cart_rule_combination" ("id_cart_rule_1");
CREATE INDEX "PREFIX_cart_rule_combination_id_cart_rule_2" ON "PREFIX_cart_rule_combination" ("id_cart_rule_2");

/* @TODO : check checkProductRestrictionsFromCart() to understand the code */
CREATE TABLE "PREFIX_cart_rule_product_rule_group" (
  "id_product_rule_group" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_cart_rule" BIGINT NOT NULL,
  "quantity" BIGINT NOT NULL DEFAULT 1,
  "type" VARCHAR(255) NOT NULL DEFAULT 'at_least_one_product_rule' CHECK ("type" IN ( 'at_least_one_product_rule', 'all_product_rules' )),
  PRIMARY KEY ("id_product_rule_group")
);

/* @TODO : check checkProductRestrictionsFromCart() to understand the code */
CREATE TABLE "PREFIX_cart_rule_product_rule" (
  "id_product_rule" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_product_rule_group" BIGINT NOT NULL,
  "type" VARCHAR(255) NOT NULL CHECK ("type" IN ( 'products', 'categories', 'attributes', 'manufacturers', 'suppliers', 'combinations', 'features' )),
  PRIMARY KEY ("id_product_rule")
);

/* @TODO : check checkProductRestrictionsFromCart() to understand the code */
CREATE TABLE "PREFIX_cart_rule_product_rule_value" (
  "id_product_rule" BIGINT NOT NULL,
  "id_item" BIGINT NOT NULL,
  PRIMARY KEY ("id_product_rule", "id_item")
);

/* Association between a cart and a promo code */
CREATE TABLE "PREFIX_cart_cart_rule" (
  "id_cart" BIGINT NOT NULL,
  "id_cart_rule" BIGINT NOT NULL,
  PRIMARY KEY ("id_cart", "id_cart_rule")
);
CREATE INDEX "PREFIX_cart_cart_rule_id_cart_rule_idx" ON "PREFIX_cart_cart_rule" ("id_cart_rule");

/* Association between a shop and a promo code */
CREATE TABLE "PREFIX_cart_rule_shop" (
  "id_cart_rule" BIGINT NOT NULL,
  "id_shop" BIGINT NOT NULL,
  PRIMARY KEY ("id_cart_rule", "id_shop")
);

/* Discount types for compatibility */
CREATE TABLE "PREFIX_cart_rule_type" (
  "id_cart_rule_type" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "discount_type" VARCHAR(128) NOT NULL,
  "is_core" SMALLINT NOT NULL DEFAULT '0',
  "active" SMALLINT NOT NULL DEFAULT '1',
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_cart_rule_type"),
  CONSTRAINT "PREFIX_cart_rule_type_discount_type" UNIQUE ("discount_type")
);

/* Localized names for cart rule types */
CREATE TABLE "PREFIX_cart_rule_type_lang" (
  "id_cart_rule_type" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "name" VARCHAR(254) NOT NULL,
  "description" TEXT,
  PRIMARY KEY ("id_cart_rule_type", "id_lang")
);

/* Cart rule compatibility table */
CREATE TABLE "PREFIX_cart_rule_compatible_types" (
  "id_cart_rule" BIGINT NOT NULL,
  "id_cart_rule_type" BIGINT NOT NULL,
  PRIMARY KEY ("id_cart_rule", "id_cart_rule_type")
);
CREATE INDEX "PREFIX_cart_rule_compatible_types_id_cart_rule" ON "PREFIX_cart_rule_compatible_types" ("id_cart_rule");
CREATE INDEX "PREFIX_cart_rule_compatible_types_id_cart_rule_type" ON "PREFIX_cart_rule_compatible_types" ("id_cart_rule_type");

/* List of products inside a cart */
CREATE TABLE "PREFIX_cart_product" (
  "id_cart" BIGINT NOT NULL,
  "id_product" BIGINT NOT NULL,
  "id_address_delivery" BIGINT NOT NULL DEFAULT '0',
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_product_attribute" BIGINT NOT NULL DEFAULT '0',
  "id_customization" BIGINT NOT NULL DEFAULT '0',
  "quantity" BIGINT NOT NULL DEFAULT '0',
  "date_add" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_cart", "id_product", "id_product_attribute", "id_customization", "id_address_delivery")
);
CREATE INDEX "PREFIX_cart_product_id_product_attribute" ON "PREFIX_cart_product" ("id_product_attribute");
CREATE INDEX "PREFIX_cart_product_id_cart_order" ON "PREFIX_cart_product" ("id_cart", "date_add", "id_product", "id_product_attribute");

/* List of product categories */
CREATE TABLE "PREFIX_category" (
  "id_category" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_parent" BIGINT NOT NULL,
  "id_shop_default" BIGINT NOT NULL DEFAULT 1,
  "level_depth" SMALLINT NOT NULL DEFAULT '0',
  "nleft" BIGINT NOT NULL DEFAULT '0',
  "nright" BIGINT NOT NULL DEFAULT '0',
  "active" SMALLINT NOT NULL DEFAULT '0',
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  "redirect_type" VARCHAR(255) NOT NULL DEFAULT '301' CHECK ("redirect_type" IN ( '404', '410', '301', '302' )),
  "id_type_redirected" BIGINT NOT NULL DEFAULT '0',
  "position" BIGINT NOT NULL DEFAULT '0',
  "is_root_category" SMALLINT NOT NULL DEFAULT '0',
  PRIMARY KEY ("id_category")
);
CREATE INDEX "PREFIX_category_category_parent" ON "PREFIX_category" ("id_parent");
CREATE INDEX "PREFIX_category_nleftrightactive" ON "PREFIX_category" ("nleft", "nright", "active");
CREATE INDEX "PREFIX_category_level_depth" ON "PREFIX_category" ("level_depth");
CREATE INDEX "PREFIX_category_nright" ON "PREFIX_category" ("nright");
CREATE INDEX "PREFIX_category_activenleft" ON "PREFIX_category" ("active", "nleft");
CREATE INDEX "PREFIX_category_activenright" ON "PREFIX_category" ("active", "nright");

/* Association between a product category and a group of customer */
CREATE TABLE "PREFIX_category_group" (
  "id_category" BIGINT NOT NULL,
  "id_group" BIGINT NOT NULL,
  PRIMARY KEY ("id_category", "id_group")
);
CREATE INDEX "PREFIX_category_group_id_category" ON "PREFIX_category_group" ("id_category");
CREATE INDEX "PREFIX_category_group_id_group" ON "PREFIX_category_group" ("id_group");

/* Localized product category infos */
CREATE TABLE "PREFIX_category_lang" (
  "id_category" BIGINT NOT NULL,
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_lang" BIGINT NOT NULL,
  "name" VARCHAR(128) NOT NULL,
  "description" TEXT,
  "additional_description" TEXT,
  "link_rewrite" VARCHAR(128) NOT NULL,
  "meta_title" VARCHAR(255) DEFAULT NULL,
  "meta_description" VARCHAR(512) DEFAULT NULL,
  PRIMARY KEY ("id_category", "id_shop", "id_lang")
);
CREATE INDEX "PREFIX_category_lang_category_name" ON "PREFIX_category_lang" ("name");

/* Association between a product category and a product */
CREATE TABLE "PREFIX_category_product" (
  "id_category" BIGINT NOT NULL,
  "id_product" BIGINT NOT NULL,
  "position" BIGINT NOT NULL DEFAULT '0',
  PRIMARY KEY ("id_category", "id_product")
);
CREATE INDEX "PREFIX_category_product_id_product_idx" ON "PREFIX_category_product" ("id_product");
CREATE INDEX "PREFIX_category_product_id_category_position_idx" ON "PREFIX_category_product" ("id_category", "position");

/* Information on content block position and category */
CREATE TABLE "PREFIX_cms" (
  "id_cms" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_cms_category" BIGINT NOT NULL,
  "position" BIGINT NOT NULL DEFAULT '0',
  "active" SMALLINT NOT NULL DEFAULT '0',
  "indexation" SMALLINT NOT NULL DEFAULT '1',
  PRIMARY KEY ("id_cms")
);

/* Localized CMS infos */
CREATE TABLE "PREFIX_cms_lang" (
  "id_cms" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "meta_title" VARCHAR(255) NOT NULL,
  "head_seo_title" VARCHAR(255) DEFAULT NULL,
  "meta_description" VARCHAR(512) DEFAULT NULL,
  "content" TEXT,
  "link_rewrite" VARCHAR(128) NOT NULL,
  PRIMARY KEY ("id_cms", "id_shop", "id_lang")
);

/* CMS category informations */
CREATE TABLE "PREFIX_cms_category" (
  "id_cms_category" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_parent" BIGINT NOT NULL,
  "level_depth" SMALLINT NOT NULL DEFAULT '0',
  "active" SMALLINT NOT NULL DEFAULT '0',
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  "position" BIGINT NOT NULL DEFAULT '0',
  PRIMARY KEY ("id_cms_category")
);
CREATE INDEX "PREFIX_cms_category_category_parent" ON "PREFIX_cms_category" ("id_parent");

/* Localized CMS category info */
CREATE TABLE "PREFIX_cms_category_lang" (
  "id_cms_category" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "name" VARCHAR(128) NOT NULL,
  "description" TEXT,
  "link_rewrite" VARCHAR(128) NOT NULL,
  "meta_title" VARCHAR(255) DEFAULT NULL,
  "meta_description" VARCHAR(512) DEFAULT NULL,
  PRIMARY KEY ("id_cms_category", "id_shop", "id_lang")
);
CREATE INDEX "PREFIX_cms_category_lang_category_name" ON "PREFIX_cms_category_lang" ("name");

/* Association between a CMS category and a shop */
CREATE TABLE "PREFIX_cms_category_shop" (
  "id_cms_category" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_shop" BIGINT NOT NULL,
  PRIMARY KEY ("id_cms_category", "id_shop")
);
CREATE INDEX "PREFIX_cms_category_shop_id_shop" ON "PREFIX_cms_category_shop" ("id_shop");

/* Store the configuration, depending on the shop & the group. See configuration.xml to have the list of
existing variables */
CREATE TABLE "PREFIX_configuration" (
  "id_configuration" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_shop_group" BIGINT DEFAULT NULL,
  "id_shop" BIGINT DEFAULT NULL,
  "name" VARCHAR(254) NOT NULL,
  "value" TEXT,
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_configuration")
);
CREATE INDEX "PREFIX_configuration_name" ON "PREFIX_configuration" ("name");
CREATE INDEX "PREFIX_configuration_id_shop" ON "PREFIX_configuration" ("id_shop");
CREATE INDEX "PREFIX_configuration_id_shop_group" ON "PREFIX_configuration" ("id_shop_group");

/* Localized configuration info */
CREATE TABLE "PREFIX_configuration_lang" (
  "id_configuration" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "value" TEXT,
  "date_upd" TIMESTAMP DEFAULT NULL,
  PRIMARY KEY ("id_configuration", "id_lang")
);

/* Store the KPI configuration variables (dashboard) */
CREATE TABLE "PREFIX_configuration_kpi" (
  "id_configuration_kpi" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_shop_group" BIGINT DEFAULT NULL,
  "id_shop" BIGINT DEFAULT NULL,
  "name" VARCHAR(64) NOT NULL,
  "value" TEXT,
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_configuration_kpi")
);
CREATE INDEX "PREFIX_configuration_kpi_name" ON "PREFIX_configuration_kpi" ("name");
CREATE INDEX "PREFIX_configuration_kpi_id_shop" ON "PREFIX_configuration_kpi" ("id_shop");
CREATE INDEX "PREFIX_configuration_kpi_id_shop_group" ON "PREFIX_configuration_kpi" ("id_shop_group");

/* Localized KPI configuration label */
CREATE TABLE "PREFIX_configuration_kpi_lang" (
  "id_configuration_kpi" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "value" TEXT,
  "date_upd" TIMESTAMP DEFAULT NULL,
  PRIMARY KEY ("id_configuration_kpi", "id_lang")
);

/* User connections log. See PS_STATSDATA_PAGESVIEWS variable */
CREATE TABLE "PREFIX_connections" (
  "id_connections" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_shop_group" BIGINT NOT NULL DEFAULT '1',
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_guest" BIGINT NOT NULL,
  "id_page" BIGINT NOT NULL,
  "ip_address" BIGINT NULL DEFAULT NULL,
  "date_add" TIMESTAMP NOT NULL,
  "http_referer" VARCHAR(255) DEFAULT NULL,
  PRIMARY KEY ("id_connections")
);
CREATE INDEX "PREFIX_connections_id_guest" ON "PREFIX_connections" ("id_guest");
CREATE INDEX "PREFIX_connections_date_add" ON "PREFIX_connections" ("date_add");
CREATE INDEX "PREFIX_connections_id_page" ON "PREFIX_connections" ("id_page");

/* User connection pages log. See PS_STATSDATA_CUSTOMER_PAGESVIEWS variable */
CREATE TABLE "PREFIX_connections_page" (
  "id_connections" BIGINT NOT NULL,
  "id_page" BIGINT NOT NULL,
  "time_start" TIMESTAMP NOT NULL,
  "time_end" TIMESTAMP DEFAULT NULL,
  PRIMARY KEY ("id_connections", "id_page", "time_start")
);

/* User connection source log. */
CREATE TABLE "PREFIX_connections_source" (
  "id_connections_source" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_connections" BIGINT NOT NULL,
  "http_referer" VARCHAR(255) DEFAULT NULL,
  "request_uri" VARCHAR(255) DEFAULT NULL,
  "keywords" VARCHAR(255) DEFAULT NULL,
  "date_add" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_connections_source")
);
CREATE INDEX "PREFIX_connections_source_connections" ON "PREFIX_connections_source" ("id_connections");
CREATE INDEX "PREFIX_connections_source_orderby" ON "PREFIX_connections_source" ("date_add");
CREATE INDEX "PREFIX_connections_source_http_referer" ON "PREFIX_connections_source" ("http_referer");
CREATE INDEX "PREFIX_connections_source_request_uri" ON "PREFIX_connections_source" ("request_uri");

/* Store technical contact informations */
CREATE TABLE "PREFIX_contact" (
  "id_contact" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "email" VARCHAR(255) NOT NULL,
  "customer_service" SMALLINT NOT NULL DEFAULT '0',
  "position" SMALLINT NOT NULL DEFAULT '0',
  PRIMARY KEY ("id_contact")
);

/* Localized technical contact infos */
CREATE TABLE "PREFIX_contact_lang" (
  "id_contact" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "description" TEXT,
  PRIMARY KEY ("id_contact", "id_lang")
);

/* Country specific data */
CREATE TABLE "PREFIX_country" (
  "id_country" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_zone" BIGINT NOT NULL,
  "id_currency" BIGINT NOT NULL DEFAULT '0',
  "iso_code" VARCHAR(3) NOT NULL,
  "call_prefix" INTEGER NOT NULL DEFAULT '0',
  "active" SMALLINT NOT NULL DEFAULT '0',
  "contains_states" SMALLINT NOT NULL DEFAULT '0',
  "need_identification_number" SMALLINT NOT NULL DEFAULT '0',
  "need_zip_code" SMALLINT NOT NULL DEFAULT '1',
  "zip_code_format" VARCHAR(12) NOT NULL DEFAULT '',
  "display_tax_label" SMALLINT NOT NULL,
  PRIMARY KEY ("id_country")
);
CREATE INDEX "PREFIX_country_country_iso_code" ON "PREFIX_country" ("iso_code");
