/* currencies allowed for each module */
CREATE TABLE "PREFIX_module_currency" (
  "id_module" BIGINT NOT NULL,
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_currency" INTEGER NOT NULL,
  PRIMARY KEY ("id_module", "id_shop", "id_currency")
);
CREATE INDEX "PREFIX_module_currency_id_module" ON "PREFIX_module_currency" ("id_module");

/* groups allowed for each module */
CREATE TABLE "PREFIX_module_group" (
  "id_module" BIGINT NOT NULL,
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_group" BIGINT NOT NULL,
  PRIMARY KEY ("id_module", "id_shop", "id_group")
);

/* carriers allowed for each module */
CREATE TABLE "PREFIX_module_carrier" (
  "id_module" BIGINT NOT NULL,
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_reference" INTEGER NOT NULL,
  PRIMARY KEY ("id_module", "id_shop", "id_reference")
);

/* List of OS (used in guest stats) */
CREATE TABLE "PREFIX_operating_system" (
  "id_operating_system" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" VARCHAR(64) DEFAULT NULL,
  PRIMARY KEY ("id_operating_system")
);

/* List of orders */
CREATE TABLE "PREFIX_orders" (
  "id_order" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "reference" VARCHAR(255),
  "id_shop_group" BIGINT NOT NULL DEFAULT '1',
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_carrier" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "id_customer" BIGINT NOT NULL,
  "id_cart" BIGINT NOT NULL,
  "id_currency" BIGINT NOT NULL,
  "id_address_delivery" BIGINT NOT NULL,
  "id_address_invoice" BIGINT NOT NULL,
  "current_state" BIGINT NOT NULL,
  "secure_key" VARCHAR(32) NOT NULL DEFAULT '-1',
  "payment" VARCHAR(255) NOT NULL,
  "conversion_rate" NUMERIC(13, 6) NOT NULL DEFAULT 1,
  "module" VARCHAR(255) DEFAULT NULL,
  "recyclable" SMALLINT NOT NULL DEFAULT '0',
  "gift" SMALLINT NOT NULL DEFAULT '0',
  "gift_message" TEXT,
  "mobile_theme" SMALLINT NOT NULL DEFAULT '0',
  "total_discounts" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_discounts_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_discounts_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_paid" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_paid_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_paid_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_paid_real" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_products" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_products_wt" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_shipping" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_shipping_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_shipping_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "carrier_tax_rate" NUMERIC(10, 3) NOT NULL DEFAULT '0.00',
  "total_wrapping" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_wrapping_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_wrapping_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "round_mode" SMALLINT NOT NULL DEFAULT '2',
  "round_type" SMALLINT NOT NULL DEFAULT '1',
  "invoice_number" BIGINT NOT NULL DEFAULT '0',
  "delivery_number" BIGINT NOT NULL DEFAULT '0',
  "invoice_date" TIMESTAMP NOT NULL,
  "delivery_date" TIMESTAMP NOT NULL,
  "valid" BIGINT NOT NULL DEFAULT '0',
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  "note" TEXT,
  PRIMARY KEY ("id_order")
);
CREATE INDEX "PREFIX_orders_reference" ON "PREFIX_orders" ("reference");
CREATE INDEX "PREFIX_orders_id_customer" ON "PREFIX_orders" ("id_customer");
CREATE INDEX "PREFIX_orders_id_cart" ON "PREFIX_orders" ("id_cart");
CREATE INDEX "PREFIX_orders_invoice_number" ON "PREFIX_orders" ("invoice_number");
CREATE INDEX "PREFIX_orders_id_carrier" ON "PREFIX_orders" ("id_carrier");
CREATE INDEX "PREFIX_orders_id_lang" ON "PREFIX_orders" ("id_lang");
CREATE INDEX "PREFIX_orders_id_currency" ON "PREFIX_orders" ("id_currency");
CREATE INDEX "PREFIX_orders_id_address_delivery" ON "PREFIX_orders" ("id_address_delivery");
CREATE INDEX "PREFIX_orders_id_address_invoice" ON "PREFIX_orders" ("id_address_invoice");
CREATE INDEX "PREFIX_orders_id_shop_group" ON "PREFIX_orders" ("id_shop_group");
CREATE INDEX "PREFIX_orders_current_state_idx" ON "PREFIX_orders" ("current_state");
CREATE INDEX "PREFIX_orders_id_shop" ON "PREFIX_orders" ("id_shop");
CREATE INDEX "PREFIX_orders_date_add" ON "PREFIX_orders" ("date_add");
CREATE INDEX "PREFIX_orders_invoice_date" ON "PREFIX_orders" ("invoice_date");

/* Order tax detail */
CREATE TABLE "PREFIX_order_detail_tax" (
  "id_order_detail" INTEGER NOT NULL,
  "id_tax" INTEGER NOT NULL,
  "unit_amount" NUMERIC(16, 6) NOT NULL DEFAULT '0.00',
  "total_amount" NUMERIC(16, 6) NOT NULL DEFAULT '0.00'
);
CREATE INDEX "PREFIX_order_detail_tax_id_order_detail_idx" ON "PREFIX_order_detail_tax" ("id_order_detail");
CREATE INDEX "PREFIX_order_detail_tax_id_tax" ON "PREFIX_order_detail_tax" ("id_tax");

/* list of invoice */
CREATE TABLE "PREFIX_order_invoice" (
  "id_order_invoice" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_order" INTEGER NOT NULL,
  "number" INTEGER NOT NULL,
  "delivery_number" INTEGER NOT NULL,
  "delivery_date" TIMESTAMP,
  "total_discount_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_discount_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_paid_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_paid_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_products" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_products_wt" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_shipping_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_shipping_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "shipping_tax_computation_method" BIGINT NOT NULL,
  "total_wrapping_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "total_wrapping_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.00',
  "shop_address" TEXT DEFAULT NULL,
  "note" TEXT,
  "date_add" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_order_invoice")
);
CREATE INDEX "PREFIX_order_invoice_id_order" ON "PREFIX_order_invoice" ("id_order");

/* global invoice tax */
CREATE TABLE IF NOT EXISTS "PREFIX_order_invoice_tax" (
  "id_order_invoice" INTEGER NOT NULL,
  "type" VARCHAR(15) NOT NULL,
  "id_tax" INTEGER NOT NULL,
  "amount" NUMERIC(10, 6) NOT NULL DEFAULT '0.000000'
);
CREATE INDEX "PREFIX_order_invoice_tax_id_tax" ON "PREFIX_order_invoice_tax" ("id_tax");

/* order detail (every product inside an order) */
CREATE TABLE "PREFIX_order_detail" (
  "id_order_detail" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_order" BIGINT NOT NULL,
  "id_order_invoice" INTEGER DEFAULT NULL,
  "id_warehouse" BIGINT DEFAULT '0',
  "id_shop" BIGINT NOT NULL,
  "product_id" BIGINT NOT NULL,
  "product_attribute_id" BIGINT DEFAULT NULL,
  "id_customization" BIGINT DEFAULT 0,
  "product_name" TEXT NOT NULL,
  "product_quantity" BIGINT NOT NULL DEFAULT '0',
  "product_quantity_in_stock" INTEGER NOT NULL DEFAULT '0',
  "product_quantity_refunded" BIGINT NOT NULL DEFAULT '0',
  "product_quantity_return" BIGINT NOT NULL DEFAULT '0',
  "product_quantity_reinjected" BIGINT NOT NULL DEFAULT '0',
  "product_price" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "reduction_percent" NUMERIC(5, 2) NOT NULL DEFAULT '0.00',
  "reduction_amount" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "reduction_amount_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "reduction_amount_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "group_reduction" NUMERIC(5, 2) NOT NULL DEFAULT '0.00',
  "product_quantity_discount" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "product_ean13" VARCHAR(20) DEFAULT NULL,
  "product_isbn" VARCHAR(32) DEFAULT NULL,
  "product_upc" VARCHAR(12) DEFAULT NULL,
  "product_mpn" VARCHAR(40) DEFAULT NULL,
  "product_reference" VARCHAR(64) DEFAULT NULL,
  "product_supplier_reference" VARCHAR(64) DEFAULT NULL,
  "product_weight" NUMERIC(20, 6) NOT NULL,
  "id_tax_rules_group" BIGINT DEFAULT '0',
  "tax_computation_method" SMALLINT NOT NULL DEFAULT '0',
  "tax_name" VARCHAR(16) NOT NULL,
  "tax_rate" NUMERIC(10, 3) NOT NULL DEFAULT '0.000',
  "ecotax" NUMERIC(17, 6) NOT NULL DEFAULT '0.000000',
  "ecotax_tax_rate" NUMERIC(5, 3) NOT NULL DEFAULT '0.000',
  "discount_quantity_applied" SMALLINT NOT NULL DEFAULT '0',
  "download_hash" VARCHAR(255) DEFAULT NULL,
  "download_nb" BIGINT DEFAULT '0',
  "download_deadline" TIMESTAMP DEFAULT NULL,
  "total_price_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "total_price_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "unit_price_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "unit_price_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "total_shipping_price_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "total_shipping_price_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "purchase_supplier_price" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "original_product_price" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "original_wholesale_price" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "total_refunded_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "total_refunded_tax_incl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  PRIMARY KEY ("id_order_detail")
);
CREATE INDEX "PREFIX_order_detail_order_detail_order" ON "PREFIX_order_detail" ("id_order");
CREATE INDEX "PREFIX_order_detail_product_id" ON "PREFIX_order_detail" ("product_id", "product_attribute_id");
CREATE INDEX "PREFIX_order_detail_product_attribute_id" ON "PREFIX_order_detail" ("product_attribute_id");
CREATE INDEX "PREFIX_order_detail_id_tax_rules_group" ON "PREFIX_order_detail" ("id_tax_rules_group");
CREATE INDEX "PREFIX_order_detail_id_order_id_order_detail" ON "PREFIX_order_detail" ("id_order", "id_order_detail");

/* Promo code used in the order */
CREATE TABLE "PREFIX_order_cart_rule" (
  "id_order_cart_rule" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_order" BIGINT NOT NULL,
  "id_cart_rule" BIGINT NOT NULL,
  "id_order_invoice" BIGINT DEFAULT '0',
  "name" VARCHAR(254) NOT NULL,
  "value" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "value_tax_excl" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "free_shipping" SMALLINT NOT NULL DEFAULT '0',
  "deleted" SMALLINT NOT NULL DEFAULT '0',
  PRIMARY KEY ("id_order_cart_rule")
);
CREATE INDEX "PREFIX_order_cart_rule_id_order" ON "PREFIX_order_cart_rule" ("id_order");
CREATE INDEX "PREFIX_order_cart_rule_id_cart_rule" ON "PREFIX_order_cart_rule" ("id_cart_rule");

/* order transactional information */
CREATE TABLE "PREFIX_order_history" (
  "id_order_history" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_employee" BIGINT NOT NULL,
  "id_order" BIGINT NOT NULL,
  "id_order_state" BIGINT NOT NULL,
  "date_add" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_order_history")
);
CREATE INDEX "PREFIX_order_history_order_history_order" ON "PREFIX_order_history" ("id_order");
CREATE INDEX "PREFIX_order_history_id_employee" ON "PREFIX_order_history" ("id_employee");
CREATE INDEX "PREFIX_order_history_id_order_state" ON "PREFIX_order_history" ("id_order_state");

/* Type of predefined message that can be inserted to an order */
CREATE TABLE "PREFIX_order_message" (
  "id_order_message" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "date_add" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_order_message")
);

/* Localized predefined order message */
CREATE TABLE "PREFIX_order_message_lang" (
  "id_order_message" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "name" VARCHAR(128) NOT NULL,
  "message" TEXT NOT NULL,
  PRIMARY KEY ("id_order_message", "id_lang")
);

/* Return state associated with an order */
CREATE TABLE "PREFIX_order_return" (
  "id_order_return" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_customer" BIGINT NOT NULL,
  "id_order" BIGINT NOT NULL,
  "state" SMALLINT NOT NULL DEFAULT '1',
  "question" TEXT NOT NULL,
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_order_return")
);
CREATE INDEX "PREFIX_order_return_order_return_customer" ON "PREFIX_order_return" ("id_customer");
CREATE INDEX "PREFIX_order_return_id_order" ON "PREFIX_order_return" ("id_order");

/* Return detail for each product inside an order */
CREATE TABLE "PREFIX_order_return_detail" (
  "id_order_return" BIGINT NOT NULL,
  "id_order_detail" BIGINT NOT NULL,
  "id_customization" BIGINT NOT NULL DEFAULT '0',
  "product_quantity" BIGINT NOT NULL DEFAULT '0',
  "cancelled" SMALLINT NOT NULL DEFAULT '0',
  PRIMARY KEY ("id_order_return", "id_order_detail", "id_customization")
);

/* List of possible return states color */
CREATE TABLE "PREFIX_order_return_state" (
  "id_order_return_state" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "color" VARCHAR(32) DEFAULT NULL,
  "is_cancelling_return" SMALLINT NOT NULL DEFAULT '0',
  PRIMARY KEY ("id_order_return_state")
);

/* Localized return states name */
CREATE TABLE "PREFIX_order_return_state_lang" (
  "id_order_return_state" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "name" VARCHAR(64) NOT NULL,
  PRIMARY KEY ("id_order_return_state", "id_lang")
);

/* Order slip info */
CREATE TABLE "PREFIX_order_slip" (
  "id_order_slip" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "conversion_rate" NUMERIC(13, 6) NOT NULL DEFAULT 1,
  "id_customer" BIGINT NOT NULL,
  "id_order" BIGINT NOT NULL,
  "total_products_tax_excl" NUMERIC(20, 6) NULL,
  "total_products_tax_incl" NUMERIC(20, 6) NULL,
  "total_shipping_tax_excl" NUMERIC(20, 6) NULL,
  "total_shipping_tax_incl" NUMERIC(20, 6) NULL,
  "shipping_cost" SMALLINT NOT NULL DEFAULT '0',
  "amount" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "shipping_cost_amount" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "partial" SMALLINT NOT NULL,
  "order_slip_type" SMALLINT NOT NULL DEFAULT '0',
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  PRIMARY KEY ("id_order_slip")
);
CREATE INDEX "PREFIX_order_slip_order_slip_customer" ON "PREFIX_order_slip" ("id_customer");
CREATE INDEX "PREFIX_order_slip_id_order" ON "PREFIX_order_slip" ("id_order");

/* Detail of the order slip (every product) */
CREATE TABLE "PREFIX_order_slip_detail" (
  "id_order_slip" BIGINT NOT NULL,
  "id_order_detail" BIGINT NOT NULL,
  "product_quantity" BIGINT NOT NULL DEFAULT '0',
  "unit_price_tax_excl" NUMERIC(20, 6) NULL,
  "unit_price_tax_incl" NUMERIC(20, 6) NULL,
  "total_price_tax_excl" NUMERIC(20, 6) NULL,
  "total_price_tax_incl" NUMERIC(20, 6),
  "amount_tax_excl" NUMERIC(20, 6) DEFAULT NULL,
  "amount_tax_incl" NUMERIC(20, 6) DEFAULT NULL,
  PRIMARY KEY ("id_order_slip", "id_order_detail")
);

/* List of available order states */
CREATE TABLE "PREFIX_order_state" (
  "id_order_state" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "invoice" SMALLINT DEFAULT '0',
  "send_email" SMALLINT NOT NULL DEFAULT '0',
  "module_name" VARCHAR(255) NULL DEFAULT NULL,
  "color" VARCHAR(32) DEFAULT NULL,
  "unremovable" SMALLINT NOT NULL,
  "hidden" SMALLINT NOT NULL DEFAULT '0',
  "logable" SMALLINT NOT NULL DEFAULT '0',
  "delivery" SMALLINT NOT NULL DEFAULT '0',
  "shipped" SMALLINT NOT NULL DEFAULT '0',
  "paid" SMALLINT NOT NULL DEFAULT '0',
  "pdf_invoice" SMALLINT NOT NULL default '0',
  "pdf_delivery" SMALLINT NOT NULL default '0',
  "deleted" SMALLINT NOT NULL DEFAULT '0',
  PRIMARY KEY ("id_order_state")
);
CREATE INDEX "PREFIX_order_state_module_name" ON "PREFIX_order_state" ("module_name");

/* Localized order state */
CREATE TABLE "PREFIX_order_state_lang" (
  "id_order_state" BIGINT NOT NULL,
  "id_lang" BIGINT NOT NULL,
  "name" VARCHAR(64) NOT NULL,
  "template" VARCHAR(64) NOT NULL,
  PRIMARY KEY ("id_order_state", "id_lang")
);

/* Define which products / quantities define a pack. A product could be a pack */
CREATE TABLE "PREFIX_pack" (
  "id_product_pack" BIGINT NOT NULL,
  "id_product_item" BIGINT NOT NULL,
  "id_product_attribute_item" BIGINT NOT NULL,
  "quantity" BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY ("id_product_pack", "id_product_item", "id_product_attribute_item")
);
CREATE INDEX "PREFIX_pack_product_item" ON "PREFIX_pack" ("id_product_item", "id_product_attribute_item");

/* page stats (PS_STATSDATA_CUSTOMER_PAGESVIEWS) */
CREATE TABLE "PREFIX_page" (
  "id_page" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_page_type" BIGINT NOT NULL,
  "id_object" BIGINT DEFAULT NULL,
  PRIMARY KEY ("id_page")
);
CREATE INDEX "PREFIX_page_id_page_type" ON "PREFIX_page" ("id_page_type");
CREATE INDEX "PREFIX_page_id_object" ON "PREFIX_page" ("id_object");

/* List of page type (stats) */
CREATE TABLE "PREFIX_page_type" (
  "id_page_type" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" VARCHAR(255) NOT NULL,
  PRIMARY KEY ("id_page_type")
);
CREATE INDEX "PREFIX_page_type_name" ON "PREFIX_page_type" ("name");

/* Page viewed (stats) */
CREATE TABLE "PREFIX_page_viewed" (
  "id_page" BIGINT NOT NULL,
  "id_shop_group" BIGINT NOT NULL DEFAULT '1',
  "id_shop" BIGINT NOT NULL DEFAULT '1',
  "id_date_range" BIGINT NOT NULL,
  "counter" BIGINT NOT NULL,
  PRIMARY KEY ("id_page", "id_date_range", "id_shop")
);

/* Payment info (see payment_invoice) */
CREATE TABLE "PREFIX_order_payment" (
  "id_order_payment" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "order_reference" VARCHAR(255),
  "id_currency" BIGINT NOT NULL,
  "amount" NUMERIC(20, 6) NOT NULL,
  "payment_method" VARCHAR(255) NOT NULL,
  "conversion_rate" NUMERIC(13, 6) NOT NULL DEFAULT 1,
  "transaction_id" VARCHAR(254) NULL,
  "card_number" VARCHAR(254) NULL,
  "card_brand" VARCHAR(254) NULL,
  "card_expiration" CHAR(7) NULL,
  "card_holder" VARCHAR(254) NULL,
  "date_add" TIMESTAMP NOT NULL,
  "id_employee" INTEGER NULL,
  PRIMARY KEY ("id_order_payment")
);
CREATE INDEX "PREFIX_order_payment_order_reference" ON "PREFIX_order_payment" ("order_reference");

/* list of products */
CREATE TABLE "PREFIX_product" (
  "id_product" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id_supplier" BIGINT DEFAULT NULL,
  "id_manufacturer" BIGINT DEFAULT NULL,
  "id_category_default" BIGINT DEFAULT NULL,
  "id_shop_default" BIGINT NOT NULL DEFAULT 1,
  "id_tax_rules_group" BIGINT NOT NULL,
  "on_sale" SMALLINT NOT NULL DEFAULT '0',
  "online_only" SMALLINT NOT NULL DEFAULT '0',
  "ean13" VARCHAR(20) DEFAULT NULL,
  "isbn" VARCHAR(32) DEFAULT NULL,
  "upc" VARCHAR(12) DEFAULT NULL,
  "mpn" VARCHAR(40) DEFAULT NULL,
  "ecotax" NUMERIC(17, 6) NOT NULL DEFAULT '0.00',
  "quantity" INTEGER NOT NULL DEFAULT '0',
  "minimal_quantity" BIGINT NOT NULL DEFAULT '1',
  "low_stock_threshold" INTEGER NULL DEFAULT NULL,
  "low_stock_alert" SMALLINT NOT NULL DEFAULT 0,
  "price" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "wholesale_price" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "unity" VARCHAR(255) DEFAULT NULL,
  "unit_price" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "unit_price_ratio" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "additional_shipping_cost" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "reference" VARCHAR(64) DEFAULT NULL,
  "supplier_reference" VARCHAR(64) DEFAULT NULL,
  "location" VARCHAR(255) NOT NULL DEFAULT '',
  "width" NUMERIC(20, 6) NOT NULL DEFAULT '0',
  "height" NUMERIC(20, 6) NOT NULL DEFAULT '0',
  "depth" NUMERIC(20, 6) NOT NULL DEFAULT '0',
  "weight" NUMERIC(20, 6) NOT NULL DEFAULT '0',
  "out_of_stock" BIGINT NOT NULL DEFAULT '2',
  "additional_delivery_times" SMALLINT NOT NULL DEFAULT '1',
  "quantity_discount" SMALLINT DEFAULT '0',
  "customizable" SMALLINT NOT NULL DEFAULT '0',
  "uploadable_files" SMALLINT NOT NULL DEFAULT '0',
  "text_fields" SMALLINT NOT NULL DEFAULT '0',
  "active" SMALLINT NOT NULL DEFAULT '0',
  "redirect_type" VARCHAR(255) NOT NULL DEFAULT 'default' CHECK ("redirect_type" IN ( '404', '410', '301-product', '302-product', '301-category', '302-category', '200-displayed', '404-displayed', '410-displayed', 'default' )),
  "id_type_redirected" BIGINT NOT NULL DEFAULT '0',
  "available_for_order" SMALLINT NOT NULL DEFAULT '1',
  "available_date" DATE DEFAULT NULL,
  "show_condition" SMALLINT NOT NULL DEFAULT '0',
  "condition" VARCHAR(255) NOT NULL DEFAULT 'new' CHECK ("condition" IN ('new', 'used', 'refurbished', 'open_box', 'damaged', 'new_with_defects')),
  "show_price" SMALLINT NOT NULL DEFAULT '1',
  "indexed" SMALLINT NOT NULL DEFAULT '0',
  "visibility" VARCHAR(255) NOT NULL DEFAULT 'both' CHECK ("visibility" IN ( 'both', 'catalog', 'search', 'none' )),
  "cache_is_pack" SMALLINT NOT NULL DEFAULT '0',
  "cache_has_attachments" SMALLINT NOT NULL DEFAULT '0',
  "is_virtual" SMALLINT NOT NULL DEFAULT '0',
  "cache_default_attribute" BIGINT DEFAULT NULL,
  "date_add" TIMESTAMP NOT NULL,
  "date_upd" TIMESTAMP NOT NULL,
  "advanced_stock_management" SMALLINT DEFAULT '0' NOT NULL,
  "pack_stock_type" BIGINT DEFAULT '3' NOT NULL,
  "state" BIGINT NOT NULL DEFAULT '1',
  "product_type" VARCHAR(255) NOT NULL DEFAULT '' CHECK ("product_type" IN ( 'standard', 'pack', 'virtual', 'combinations', '' )),
  PRIMARY KEY ("id_product")
);
CREATE INDEX "PREFIX_product_reference_idx" ON "PREFIX_product" ("reference");
CREATE INDEX "PREFIX_product_supplier_reference_idx" ON "PREFIX_product" ("supplier_reference");
