CREATE INDEX "PREFIX_product_id_category_default" ON "PREFIX_product" ("id_category_default");
CREATE INDEX "PREFIX_product_indexed" ON "PREFIX_product" ("indexed");
CREATE INDEX "PREFIX_product_date_add" ON "PREFIX_product" ("date_add");
CREATE INDEX "PREFIX_product_state" ON "PREFIX_product" ("state", "date_upd");

/* shop specific product info */
CREATE TABLE IF NOT EXISTS "PREFIX_product_shop" (
  "id_product" BIGINT NOT NULL,
  "id_shop" BIGINT NOT NULL,
  "id_category_default" BIGINT DEFAULT NULL,
  "id_tax_rules_group" BIGINT NOT NULL,
  "on_sale" SMALLINT NOT NULL DEFAULT '0',
  "online_only" SMALLINT NOT NULL DEFAULT '0',
  "ecotax" NUMERIC(17, 6) NOT NULL DEFAULT '0.000000',
  "minimal_quantity" BIGINT NOT NULL DEFAULT '1',
  "low_stock_threshold" INTEGER NULL DEFAULT NULL,
  "low_stock_alert" SMALLINT NOT NULL DEFAULT 0,
  "price" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
  "wholesale_price" NUMERIC(20, 6) NOT NULL DEFAULT '0.000000',
